# -*- coding: utf-8 -*-
"""Regression tests for the reading-order ItemList generated by build_lore.py.

The JSON-LD must be derived from the same lore records that render the visible
reading order, so a rebuild can never drop or desynchronise itemListElement.
These tests use the repository's real records and perform no file writes.
"""
import copy
import html
import json
import re
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
import build_lore as bl  # noqa: E402

BLOCK_RE = re.compile(
    r'<script type="application/ld\+json">([\s\S]*?)</script>', re.I
)
ITEM_RE = re.compile(r'<li class="reading-item">([\s\S]*?)</li>', re.S)
H3_RE = re.compile(r'<h3>(.*?)</h3>', re.S)
FIRST_RECORD_RE = re.compile(
    r'<p class="reading-records">[\s\S]*?<a href="([^"]+)">', re.S
)


def rendered_page():
    """Mirror build_lore.main()'s data setup without writing any files."""
    sources, entries, errors, _ = bl.run_validation()
    if errors:
        raise AssertionError(f"lore validation failed: {errors[:3]}")
    entries_by_id = {e["id"]: e for e in entries}
    sources_by_id = {s["id"]: s for s in sources}
    reviewed = [
        e["verification"]["last_reviewed"]
        for e in entries
        if e.get("verification", {}).get("last_reviewed")
    ]
    bl.DEFAULT_MODIFIED = max(reviewed) if reviewed else None
    reading_order = bl.load_reading_order()
    page = bl.render_reading_order(reading_order, entries_by_id, sources_by_id)
    return page, reading_order, entries_by_id


def jsonld(page):
    blocks = BLOCK_RE.findall(page)
    assert len(blocks) == 1, f"expected one JSON-LD block, got {len(blocks)}"
    return json.loads(blocks[0])


def visible_items(page):
    result = []
    for li in ITEM_RE.findall(page):
        name = html.unescape(H3_RE.search(li).group(1)).strip()
        url = FIRST_RECORD_RE.search(li).group(1)
        result.append((name, bl.BASE_URL + url))
    return result


class ReadingOrderJsonLdTests(unittest.TestCase):
    def test_exactly_ten_list_items_for_current_data(self):
        data = jsonld(rendered_page()[0])
        self.assertEqual(data["@type"], "ItemList")
        self.assertEqual(len(data["itemListElement"]), 10)

    def test_positions_sequential_from_one(self):
        data = jsonld(rendered_page()[0])
        self.assertEqual(
            [i["position"] for i in data["itemListElement"]], list(range(1, 11))
        )

    def test_names_match_visible_headings_in_order(self):
        page = rendered_page()[0]
        data = jsonld(page)
        self.assertEqual(
            [i["name"] for i in data["itemListElement"]],
            [name for name, _ in visible_items(page)],
        )

    def test_urls_match_archive_record_destinations(self):
        page = rendered_page()[0]
        data = jsonld(page)
        self.assertEqual(
            [i["url"] for i in data["itemListElement"]],
            [url for _, url in visible_items(page)],
        )

    def test_list_item_structure_and_jsonld_validity(self):
        data = jsonld(rendered_page()[0])
        self.assertEqual(data["@context"], "https://schema.org")
        for item in data["itemListElement"]:
            self.assertEqual(item["@type"], "ListItem")
            self.assertEqual(set(item), {"@type", "position", "url", "name"})
            self.assertTrue(item["url"].startswith("https://raigulus.github.io/lore/"))
            self.assertTrue(item["name"])

    def test_generated_output_equals_current_fixed_page_jsonld(self):
        generated = jsonld(rendered_page()[0])["itemListElement"]
        on_disk = (ROOT / "lore" / "reading-order" / "index.html").read_text(encoding="utf-8")
        self.assertEqual(jsonld(on_disk)["itemListElement"], generated)

    def test_second_render_preserves_item_list(self):
        page1 = rendered_page()[0]
        page2 = rendered_page()[0]
        self.assertEqual(page1, page2)
        self.assertEqual(len(jsonld(page1)["itemListElement"]), 10)
        self.assertEqual(len(jsonld(page2)["itemListElement"]), 10)

    def test_names_and_urls_are_derived_from_source_records(self):
        _, reading_order, entries_by_id = rendered_page()
        changed = copy.deepcopy(reading_order)
        changed["groups"][0]["items"][0]["title"] = "Derived title check"
        items = bl.reading_order_list_items(changed, entries_by_id)
        self.assertEqual(items[0]["name"], "Derived title check")

        changed_entries = copy.deepcopy(entries_by_id)
        first_id = reading_order["groups"][0]["items"][0]["entry_ids"][0]
        changed_entries[first_id]["slug"] = "renamed-slug"
        items = bl.reading_order_list_items(reading_order, changed_entries)
        self.assertTrue(items[0]["url"].endswith("/lore/events/renamed-slug/"))


if __name__ == "__main__":
    unittest.main()
